  1	/**
  2	 * Tests for ralph replacement — kspec ralph deprecation and built-in agent setup.
  3	 *
  4	 * Verifies that kspec ralph commands show a helpful migration error, and that
  5	 * kspec setup creates built-in task-worker and pr-reviewer agent definitions.
  6	 *
  7	 * Task: @implement-ralph-replacement
  8	 * Spec: @ralph-replacement
  9	 */
 10	
 11	import { describe, it, expect, beforeEach, afterEach } from "vitest";
 12	import * as fs from "node:fs/promises";
 13	import * as path from "node:path";
 14	import * as YAML from "yaml";
 15	import { spawnSync } from "node:child_process";
 16	import {
 17	  CLI_PATH,
 18	  createTempDir,
 19	  cleanupTempDir,
 20	  initGitRepo,
 21	  kspec,
 22	} from "./helpers/cli.js";
 23	
 24	// ─── Helpers ─────────────────────────────────────────────────────────────────
 25	
 26	interface CliResult {
 27	  stdout: string;
 28	  stderr: string;
 29	  exitCode: number;
 30	}
 31	
 32	function runCli(args: string[], cwd: string): CliResult {
 33	  const result = spawnSync("node", [CLI_PATH, ...args], {
 34	    cwd,
 35	    encoding: "utf-8",
 36	    timeout: 30000,
 37	    env: { ...process.env, KSPEC_AUTHOR: "@test" },
 38	  });
 39	  return {
 40	    stdout: result.stdout || "",
 41	    stderr: result.stderr || "",
 42	    exitCode: result.status ?? 1,
 43	  };
 44	}
 45	
 46	/**
 47	 * Create a minimal kspec project in a temp dir (traditional layout, not shadow branch).
 48	 */
 49	async function setupMinimalProject(dir: string): Promise<void> {
 50	  initGitRepo(dir);
 51	  await fs.writeFile(
 52	    path.join(dir, "kynetic.yaml"),
 53	    YAML.stringify({ kynetic: "1", title: "Test Project" }),
 54	    "utf-8",
 55	  );
 56	  await fs.writeFile(
 57	    path.join(dir, "kynetic.meta.yaml"),
 58	    YAML.stringify({
 59	      kynetic_meta: "1.0",
 60	      agents: [],
 61	      workflows: [],
 62	      conventions: [],
 63	      observations: [],
 64	      skills: [],
 65	      includes: [],
 66	    }),
 67	    "utf-8",
 68	  );
 69	}
 70	
 71	// ─── Tests ────────────────────────────────────────────────────────────────────
 72	
 73	// AC: @ralph-replacement ac-1
 74	describe("kspec ralph deprecation", () => {
 75	  it("shows migration error when kspec ralph run is invoked", () => {
 76	    const result = runCli(["ralph", "run"], process.cwd());
 77	
 78	    // Should exit with code 1
 79	    expect(result.exitCode).toBe(1);
 80	
 81	    // AC: @trait-error-guidance ac-1 — description of what went wrong
 82	    expect(result.stderr).toMatch(/kspec ralph has been replaced/i);
 83	
 84	    // AC: @ralph-replacement ac-1 — lists equivalent commands
 85	    expect(result.stderr).toContain("kspec ralph run");
 86	    expect(result.stderr).toContain("kspec agent dispatch start");
 87	    expect(result.stderr).toMatch(
 88	      /kspec ralph run\s+→\s+kspec agent dispatch start/,
 89	    );
 90	    expect(result.stderr).toContain("kspec ralph --dry-run");
 91	    expect(result.stderr).toContain("kspec agent dispatch start --dry-run");
 92	  });
 93	
 94	  it("shows migration error when kspec ralph end-loop is invoked", () => {
 95	    const result = runCli(["ralph", "end-loop"], process.cwd());
 96	
 97	    // Should exit with code 1
 98	    expect(result.exitCode).toBe(1);
 99	
100	    // AC: @trait-error-guidance ac-1 — description of what went wrong
101	    expect(result.stderr).toMatch(/kspec ralph has been replaced/i);
102	
103	    // AC: @ralph-replacement ac-1 — lists equivalent commands
104	    expect(result.stderr).toContain("kspec agent end-loop");
105	  });
106	
107	  it("shows kspec setup suggestion in migration message", () => {
108	    const result = runCli(["ralph"], process.cwd());
109	
110	    // AC: @trait-error-guidance ac-2 — suggested action to resolve
111	    expect(result.stderr).toContain("kspec setup");
112	  });
113	});
114	
115	// AC: @ralph-replacement ac-2
116	describe("kspec setup built-in agents", () => {
117	  let tempDir: string;
118	
119	  beforeEach(async () => {
120	    tempDir = await createTempDir();
121	    await setupMinimalProject(tempDir);
122	  });
123	
124	  afterEach(async () => {
125	    await cleanupTempDir(tempDir);
126	  });
127	
128	  it("creates task-worker and pr-reviewer agents when project has no agents", async () => {
129	    // Run setup (no-hooks to keep it fast in tests)
130	    const result = await kspec("setup --no-hooks --skip-skills", tempDir);
131	    expect(result.exitCode).toBe(0);
132	
133	    // Read the meta manifest
134	    const metaPath = path.join(tempDir, "kynetic.meta.yaml");
135	    const raw = YAML.parse(await fs.readFile(metaPath, "utf-8")) as {
136	      agents?: Array<{ id: string; dispatch?: unknown[] }>;
137	    };
138	
139	    const agents = raw.agents || [];
140	    const agentIds = agents.map((a) => a.id);
141	
142	    // AC: @ralph-replacement ac-2 — built-in worker and reviewer created
143	    expect(agentIds).toContain("task-worker");
144	    expect(agentIds).toContain("pr-reviewer");
145	  });
146	
147	  it("task-worker has dispatch rules for task.in_progress/task.ready/task.needs_work with eligible filter", async () => {
148	    await kspec("setup --no-hooks --skip-skills", tempDir);
149	
150	    const metaPath = path.join(tempDir, "kynetic.meta.yaml");
151	    const raw = YAML.parse(await fs.readFile(metaPath, "utf-8")) as {
152	      agents?: Array<{
153	        id: string;
154	        dispatch?: Array<{ on: string; filter?: { automation?: string } }>;
155	      }>;
156	    };
157	
158	    const worker = (raw.agents || []).find((a) => a.id === "task-worker");
159	    expect(worker).toBeDefined();
160	
161	    const dispatch = worker!.dispatch || [];
162	    const events = dispatch.map((r) => r.on);
163	
164	    // AC: @ralph-replacement ac-2 — worker: task.in_progress + task.ready + task.needs_work with eligible filter
165	    expect(events).toContain("task.in_progress");
166	    expect(events).toContain("task.ready");
167	    expect(events).toContain("task.needs_work");
168	
169	    // Should have automation: eligible filter
170	    const inProgressRule = dispatch.find((r) => r.on === "task.in_progress");
171	    expect(inProgressRule?.filter?.automation).toBe("eligible");
172	    const readyRule = dispatch.find((r) => r.on === "task.ready");
173	    expect(readyRule?.filter?.automation).toBe("eligible");
174	    const needsWorkRule = dispatch.find((r) => r.on === "task.needs_work");
175	    expect(needsWorkRule?.filter?.automation).toBe("eligible");
176	  });
177	
178	  it("pr-reviewer has dispatch rule for task.pending_review", async () => {
179	    await kspec("setup --no-hooks --skip-skills", tempDir);
180	
181	    const metaPath = path.join(tempDir, "kynetic.meta.yaml");
182	    const raw = YAML.parse(await fs.readFile(metaPath, "utf-8")) as {
183	      agents?: Array<{
184	        id: string;
185	        dispatch?: Array<{ on: string }>;
186	      }>;
187	    };
188	
189	    const reviewer = (raw.agents || []).find((a) => a.id === "pr-reviewer");
190	    expect(reviewer).toBeDefined();
191	
192	    const events = (reviewer!.dispatch || []).map((r) => r.on);
193	
194	    // AC: @ralph-replacement ac-2 — reviewer: task.pending_review
195	    expect(events).toContain("task.pending_review");
196	  });
197	
198	  it("does not duplicate agents when run twice (idempotent)", async () => {
199	    await kspec("setup --no-hooks --skip-skills", tempDir);
200	    await kspec("setup --no-hooks --skip-skills", tempDir);
201	
202	    const metaPath = path.join(tempDir, "kynetic.meta.yaml");
203	    const raw = YAML.parse(await fs.readFile(metaPath, "utf-8")) as {
204	      agents?: Array<{ id: string }>;
205	    };
206	
207	    const agentIds = (raw.agents || []).map((a) => a.id);
208	    const workerCount = agentIds.filter((id) => id === "task-worker").length;
209	    const reviewerCount = agentIds.filter((id) => id === "pr-reviewer").length;
210	
211	    expect(workerCount).toBe(1);
212	    expect(reviewerCount).toBe(1);
213	  });
214	});
215	
216	// AC: @ralph-replacement ac-6
217	describe("agent dispatch template section", () => {
218	  it("06-ralph-loop.md template references agent dispatch not ralph", async () => {
219	    // Resolve the template path relative to package root
220	    const templatePath = path.join(
221	      __dirname,
222	      "..",
223	      "templates",
224	      "agents-sections",
225	      "06-ralph-loop.md",
226	    );
227	    const content = await fs.readFile(templatePath, "utf-8");
228	
229	    // Should reference agent dispatch concepts
230	    expect(content).toContain("Agent Dispatch Mode");
231	    expect(content).toContain("dispatch engine");
232	    expect(content).toContain("pr-reviewer agent");
233	
234	    // Should NOT reference ralph
235	    expect(content.toLowerCase()).not.toContain("ralph");
236	  });
237	});
238	
239	// AC: @ralph-replacement ac-8
240	describe("uncommitted changes detection", () => {
241	  let tempDir: string;
242	
243	  beforeEach(async () => {
244	    tempDir = await createTempDir();
245	    await setupMinimalProject(tempDir);
246	  });
247	
248	  afterEach(async () => {
249	    await cleanupTempDir(tempDir);
250	  });
251	
252	  it("session checkpoint warns about uncommitted changes when they exist", async () => {
253	    // Create a file change to simulate uncommitted work
254	    await fs.writeFile(
255	      path.join(tempDir, "uncommitted.ts"),
256	      "// uncommitted work\n",
257	      "utf-8",
258	    );
259	
260	    // Session checkpoint should detect the dirty working tree and block
261	    const result = await kspec(
262	      "session checkpoint --json",
263	      tempDir,
264	    );
265	
266	    // In JSON mode, checkpoint exits 0 but outputs {"decision": "block", "reason": "..."}
267	    // when uncommitted changes are detected
268	    expect(result.exitCode).toBe(0);
269	    const output = JSON.parse(result.stdout.trim()) as { decision: string; reason: string };
270	    expect(output.decision).toBe("block");
271	    expect(output.reason).toContain("uncommitted changes");
272	  });
273	});
274	
275	// ─── AC Coverage Annotations ─────────────────────────────────────────────────
276	//
277	// Own ACs covered indirectly (no dedicated test needed):
278	// AC: @ralph-replacement ac-3 — covered by ac-2 dispatch rule tests verifying worker+reviewer lifecycle match ralph behavior
279	// AC: @ralph-replacement ac-4 — N/A: workflow updates are configuration-only changes in .kspec/; verified by kspec-agents.md content, no unit test needed
280	// AC: @ralph-replacement ac-5 — N/A: skill file content changes verified by kspec-agents.md generation; no unit test needed
281	// AC: @ralph-replacement ac-7 — N/A: AC is satisfied by deletion of ralph test files; verified by CI passing without them
282	//
283	// Inherited trait ACs (@trait-error-guidance) that do not apply to the ralph deprecation stub:
284	// AC: @trait-error-guidance ac-3 — N/A: ralph stub does not perform ref lookups; no 'not found' error paths
285	// AC: @trait-error-guidance ac-4 — N/A: ralph stub has no state machine transitions; only shows migration error
286	// AC: @trait-error-guidance ac-5 — N/A: ralph stub has no field validation; only shows migration error
287	// AC: @trait-error-guidance ac-6 — N/A: ralph stub has no --json mode

